def compact(newer, older, bottommost):
    out, i, j = [], 0, 0
    while i < len(newer) or j < len(older):
        take_newer = j == len(older) or (
            i < len(newer) and newer[i].key <= older[j].key)
        if take_newer:
            e = newer[i]; i += 1
            if j < len(older) and older[j].key == e.key:
                j += 1  # older version is shadowed: skip it
        else:
            e = older[j]; j += 1
        if e.is_tombstone and bottommost:
            continue    # nothing older below: drop the marker
        out.append(e)
    return out
